def can_promote(challenger, champion, min_gain, max_slice_drop):
    reasons = []
    if challenger['overall'] - champion['overall'] < min_gain - 1e-9:
        reasons.append('overall gain too small')
    for name in sorted(champion['slices']):
        if name not in challenger['slices']:
            reasons.append('missing slice: ' + name)
        elif champion['slices'][name] - challenger['slices'][name] > max_slice_drop + 1e-9:
            reasons.append('slice drop: ' + name)
    return (not reasons), reasons
